  void MarkLoreDirty(){loreDirty=true;if(loreNotice!=null)loreNotice.Text="世界书有未保存修改；正在执行的请求继续使用原规则。";}
  void RefreshLoreList(LoreEntry select){loreList.ItemsSource=null;loreList.ItemsSource=loreDraft;loreList.SelectedItem=select??loreDraft.FirstOrDefault();}
  void FillRule(){studioLoading=true;try{var e=editingRule;ruleName.Text=e==null?"":e.Name;ruleSystem.Text=e==null?"":e.SystemMatch;ruleKeys.Text=e==null?"":e.Keywords;ruleText.Text=e==null?"":e.Content;rulePriority.Text=e==null?"0":e.Priority.ToString();ruleEnabled.IsChecked=e!=null&&e.Enabled;ruleAlways.IsChecked=e!=null&&e.Always;ruleAll.IsChecked=e!=null&&e.MatchAll;ruleScope.SelectedIndex=e!=null&&e.Scope=="recent-users"?1:0;foreach(var control in new Control[]{ruleName,ruleSystem,ruleKeys,ruleText,rulePriority,ruleEnabled,ruleAlways,ruleAll,ruleScope})control.IsEnabled=e!=null;}finally{studioLoading=false;}if(loreScroll!=null)loreScroll.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,new Action(delegate{loreScroll.ScrollToTop();}));}
  void UpdateLoreDraft(){if(studioLoading||editingRule==null)return;var e=editingRule;e.Name=ruleName.Text;e.SystemMatch=ruleSystem.Text;e.Keywords=ruleKeys.Text;e.Content=ruleText.Text;e.Enabled=ruleEnabled.IsChecked==true;e.Always=ruleAlways.IsChecked==true;e.MatchAll=ruleAll.IsChecked==true;e.Scope=ruleScope.SelectedIndex==1?"recent-users":"last-user";int priority;e.Priority=Int32.TryParse(rulePriority.Text,out priority)?priority:10001;MarkLoreDirty();loreNotice.Text="世界书有未保存修改；正在执行的请求继续使用原规则。";loreList.Items.Refresh();}
