   var split=new Grid();split.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(200)});split.ColumnDefinitions.Add(new ColumnDefinition());Put(grid,split,1);var list=new ListBox{Margin=new Thickness(0,0,12,0)};split.Children.Add(list);var detail=Input("人物方案差异",true);detail.IsReadOnly=true;Grid.SetColumn(detail,1);split.Children.Add(detail);CharacterPlan selected=null;List<EditChange> changes=null;
   Action refresh=delegate{list.ItemsSource=library.Data.Plans.Where(p=>p.NpcId==id).ToList();list.SelectedIndex=0;if(list.Items.Count==0)detail.Text="还没有此人物的方案。可将当前人物草稿保存为第一份方案。";};
   list.SelectionChanged+=delegate{selected=list.SelectedItem as CharacterPlan;changes=null;if(selected==null)return;try{var preview=new Store(store.Root,catalog,new MemoryPrefs());store.CopyDraftTo(preview);var baseline=new DraftState(preview);selected.Apply(preview,id);changes=baseline.Changes();detail.Text=changes.Count==0?"与当前人物草稿一致。":String.Join("\n\n",changes.Select(c=>c.Title+"\n当前草稿："+c.Before+"\n方案："+c.After));}catch(Exception ex){detail.Text=ex.Message;}};
   Put(grid,Actions(ActionButton("保存为新方案…",delegate{string name=AskText("保存人物方案","名称（包含当前人物未保存修改）",npc.Name+" · "+DateTime.Now.ToString("MM-dd HH:mm"));if(name==null)return;var next=CopyLibrary();if(next.Plans.Any(p=>p.NpcId==id&&p.Name==name.Trim()))throw new InvalidDataException("此人物已有同名方案，请使用不同名称。");next.Plans.Add(CharacterPlan.Capture(store,id,name));library.Save(next);refresh();}),ActionButton("删除方案",delegate{if(selected==null)return;if(MessageBox.Show(dialog,"删除方案“"+selected.Name+"”？原游戏配置不变，资料库上一版保留在 studio.json.bak。","删除方案",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;var next=CopyLibrary();next.Plans.RemoveAll(p=>p.Id==selected.Id);library.Save(next);refresh();}),ActionButton("应用到此人物草稿",delegate{if(selected==null||changes==null)throw new InvalidOperationException("请选择兼容的方案并检查差异。");selected.Apply(store,id);Filter();FillNpc();Refresh();message="已应用人物方案；退出游戏后保存补丁，再重新启动游戏。";Refresh();dialog.Close();})),2);refresh();if(planProofFolder!=null){dialog.Show();RenderDialogProof(dialog,planProofFolder,"21-character-plans");dialog.Close();}else dialog.ShowDialog();
  }
 }
